class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int n = s.size();
        unordered_map <char,int> mp;
        int j = 0;
        int ans = 0;
        for(int i=0;i<n;i++){
            mp[s[i]]++;
            while(mp[s[i]] == 2){
                mp[s[j]]--;
                if(mp[s[j]] == 0)
                    mp.erase(s[j]);
                j++;
            }
            ans = max(ans,i-j+1);
        }
        return ans;
    }
};,6,https://leetcode.com/problems/longest-substring-without-repeating-characters,https://leetcode.com/problems/longest-substring-without-repeating-characters/solutions/3736727/q3-accepted-c-sliding-win-hashmap-easiest/

class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int m = nums1.length;
        int n = nums2.length;
        List<Integer> ls = new ArrayList<>();
        int i = 0, j = 0;

        while (i < m && j < n) {
            if (nums1[i] < nums2[j]) {
                ls.add(nums1[i++]);
            } else {
                ls.add(nums2[j++]);
            }
        }

        while (i < m) ls.add(nums1[i++]);
        while (j < n) ls.add(nums2[j++]);

        int mid = ls.size()/2;
        if(ls.size() % 2 == 0){
            return (ls.get(mid-1) + ls.get(mid))/2.0;
        }else{
            return ls.get(mid);
        }
    }
