class Solution {
public:
    ListNode* mergeKLists(vector<ListNode*>&lists) 
    {
        //same concept of pair as before
        set<pair<int,int>>listmin;
        for(int i=0;i<lists.size();i++)
        {
            if(lists[i]!=NULL)
            {
                listmin.insert({lists[i]->val,i});
            }
        }
        if(listmin.empty())
        {
            return NULL;
        }
        ListNode* node=new ListNode();
        ListNode* head=node;
        while(1)
        {
            pair<int,int>x=*(listmin.begin());
            listmin.erase(listmin.begin());
            node->val=x.first;
            if(lists[x.second]->next!=NULL)
            {
                lists[x.second]=lists[x.second]->next;
                listmin.insert({lists[x.second]->val,x.second});
            }
            if(!listmin.empty())
            {
                node->next=new ListNode();
                node=node->next;
            }
            else
            {
                break;
            }
        }
        return head;
    }
};,38,https://leetcode.com/problems/merge-k-sorted-lists,https://leetcode.com/problems/merge-k-sorted-lists/solutions/3286041/two-solutions-using-minheap-and-ordered-set/

class Solution {
public:
    ListNode* swapPairs(ListNode* head) {
        // if head is NULL OR just having a single node, then no need to change anything 
        if(head == NULL || head -> next == NULL) 
        {
            return head;
        }

        ListNode* temp; // temporary pointer to store head -> next
        temp = head->next; // give temp what he want

        head->next = swapPairs(head->next->next); // changing links
        temp->next = head; // put temp -> next to head

        return temp; // now after changing links, temp act as our head
    }
};,40,https://leetcode.com/problems/swap-nodes-in-pairs,https://leetcode.com/problems/swap-nodes-in-pairs/solutions/1774708/c-visual-image-how-links-change-explained-every-step-commented-code/

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        final Map<String, Integer> counts = new HashMap<>();
        for (final String word : words) {
            counts.put(word, counts.getOrDefault(word, 0) + 1);
        }
        final List<Integer> indexes = new ArrayList<>();
        final int n = s.length(), num = words.length, len = words[0].length();
        for (int i = 0; i < n - num * len + 1; i++) {
            final Map<String, Integer> seen = new HashMap<>();
            int j = 0;
            while (j < num) {
                final String word = s.substring(i + j * len, i + (j + 1) * len);
                if (counts.containsKey(word)) {
                    seen.put(word, seen.getOrDefault(word, 0) + 1);
                    if (seen.get(word) > counts.getOrDefault(word, 0)) {
                        break;
                    }
                } else {
                    break;
                }
                j++;
            }
            if (j == num) {
                indexes.add(i);
            }
        }
        return indexes;
    }
},19,https://leetcode.com/problems/substring-with-concatenation-of-all-words,https://leetcode.com/problems/substring-with-concatenation-of-all-words/solutions/13658/easy-two-map-solution-c-java/

/**
 * @param {number[]} nums
 * @return {void} Do not return anything, modify nums in-place instead.
 */
var nextPermutation = function(nums) {
    for (let i = nums.length - 2; i >= 0; i--) {
        let currentIndexSwap = i;
        for (let j = i + 1; j < nums.length; j++) {
            if ((nums[j] > nums[i] && nums[j] < nums[currentIndexSwap]) || (nums[j] > nums[currentIndexSwap] && currentIndexSwap === i)) {
                currentIndexSwap = j;
            }
        }
        if (i !== currentIndexSwap) {
            [nums[i], nums[currentIndexSwap]] = [nums[currentIndexSwap], nums[i]];
            for (let k = i + 1; k < nums.length; k++) {
                for (let p = k + 1; p < nums.length; p++) {
                    if (nums[p] < nums[k]) {
                        [nums[k], nums[p]] = [nums[p], nums[k]];
                    }
                }
            }
            return nums;
        }
    }

    return nums.sort((a, b) => a - b);
};,47,https://leetcode.com/problems/next-permutation,https://leetcode.com/problems/next-permutation/solutions/3038512/js-easy-and-fast-solution/

class Solution {
public:
    int longestValidParentheses(string s) {
        stack<int> st;
        st.push(-1);
        int maxlen=0;
        for(int i=0;i<s.length();i++){
            char ch=s[i];
            if(ch=='(')
                st.push(i);
            else{
                st.pop();
                if(st.empty())
                st.push(i);
                else{
                    int len=i-st.top();
                    maxlen=max(len,maxlen);
                }
            }
        }
        return maxlen;
    }
};,26,https://leetcode.com/problems/longest-valid-parentheses,https://leetcode.com/problems/longest-valid-parentheses/solutions/3603982/easy-c-solution/

class Solution {
public:
    int search(vector<int>& nums, int target) {
        int n = nums.size();
        int start = 0, end = n-1;
        int mid = start + (end-start)/2;
        while(start <= end){
            if(target == nums[mid]){
                return mid;
            }
            if(nums[start] <= nums[mid]){
                if(target >= nums[start] && target < nums[mid]){
                    end = mid-1;
                }
                else start = mid+1;
            }
            else{
                if(target <= nums[end] && target > nums[mid]){
                    start = mid+1;
                }
                else {
                    end = mid-1;
                }
            }
            mid = start + (end-start)/2;
        }
        return -1;
    }
};,37,https://leetcode.com/problems/search-in-rotated-sorted-array,https://leetcode.com/problems/search-in-rotated-sorted-array/solutions/4125295/easy-c-solution-binary-search-approach-beats-100/

