class Solution {
public:
     string countAndSay(int n) {
        vector<string> v;
        string s="";
        v.push_back(s);
        for(int i=1;i<=n;i++){
            s=v[i-1];
            if(s=="") v.push_back("1");
            else{
                string ans="";
                int count=1,flag=1;
                for(int i=0;i<s.size()-1;++i){
                    if(s[i+1]==s[i]){
                        count++;
                    }
                    else{
                        ans+=(count+'0');
                        ans+=s[i];
                        count=1;
                    }  
                }
                if(flag==1){
                    ans+=(count+'0');
                    ans+=s[s.size()-1];
                }
                v.push_back(ans);
            }
        }
        return v[n];
    }
};,57,https://leetcode.com/problems/count-and-say,https://leetcode.com/problems/count-and-say/solutions/2716243/c-90-faster-than-all-easy/

class Solution {
public:
    void solve(vector<int>& candidates, int target, int ind, vector<vector<int>>& ans, vector<int>& output){
        //base case
        if(target == 0){
            ans.push_back(output);
            return;
        }
        if(target < 0){
            return;
        }

        //recursive relation
        for(int i=ind; i<candidates.size(); i++){
            output.push_back(candidates[i]);
            solve(candidates, target-candidates[i], i, ans, output);
            output.pop_back();
        }
    }


    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        vector<vector<int>> ans;
        vector<int> output;
        int ind = 0;
        solve(candidates, target, ind, ans, output);
        return ans;
    }
};,37,https://leetcode.com/problems/combination-sum,https://leetcode.com/problems/combination-sum/solutions/4389638/easy-understandable-c-solution-beats-75/

class Solution {
public:
    string multiply(string& A, string& B) {
        if(A == "0" || B == "0") return "0";                  // if either is 0, final result will be 0
		if(size(A) < size(B)) return multiply (B, A);
        string ans = "";
        for(int j = size(B)-1, pad = 0; j >= 0; j--) {
            auto res = multiplyDigit(A, B[j], pad++);         // multiply each digit of B with A considering proper padding of 0 at end
            ans = addStrings(ans, res);                       // keep adding intermediate result to final result
        }
        return ans;
    }

	// multiply a string number with a char digit
    string multiplyDigit(string& s, char c, int pad) {
        int i = size(s)-1, carry = 0, digit1 = c-'0', digit2, res;
		// the string is formed in reverse manner & then reversed at end
		// This is because it's O(1) to push at the end instead of at the start
        string ans = string(pad, '0');
        while(i >= 0) {
            digit2 = s[i--]-'0';                    // get digit of num1 to be multiplied with digit1
            res = digit1 * digit2 + carry;          // multiplication of digits + carry from previous
            carry = res / 10;                       // update carry
            ans += res%10+'0';                      // only consider last digit & add it to result
        }
        if(carry) ans += carry+'0';                 // if there's leftover carry at end after multiplying all digits
        reverse(begin(ans), end(ans));              // reverse back to get correct result
        return ans;
    }

	// adds two string numbers - https://leetcode.com/problems/add-strings/
    string addStrings(string& A, string& B) {
        if(size(A) < size(B)) return addStrings(B, A);   // we assume A is the bigger string
        int i = size(A)-1, j = size(B)-1, carry = 0, digit1, digit2, res;
        string ans = "";
        while(i >= 0) {
            digit1 = A[i--]-'0', digit2 = j >= 0 ? (B[j--]-'0') : 0;  // get digits from both numbers
            res = digit1 + digit2 + carry;               // add both digit and carry from previous
            carry = res / 10;                            // update carry
            ans += res%10+'0';                           // only consider last digit & add it to result
        }
        if(carry) ans += carry+'0';                      // if there's leftover carry at end after multiplying all digits
        reverse(begin(ans), end(ans));                   // We formed in reverse order. Reverse it back to get correct result
        return ans;
    }
};,63,https://leetcode.com/problems/multiply-strings,https://leetcode.com/problems/multiply-strings/solutions/1563536/c-simple-solution-w-explanation-and-images-school-optimized-multiplication/

class Solution {
public:
    bool isMatch(string s, string p) 
    {
        int n = s.size() ;
        int m = p.size() ;
        vector<vector<int>> dp(n+1,vector<int> (m+1,0)) ;
        dp[0][0] = 1 ;

        int k = 1 ;
        while(k <= m && p[k-1] == '*')
            dp[0][k++] = 1 ;

        for(int i = 1 ; i <= n ; i++)
            for(int j = 1 ; j <= m ; j++)
            {
                if(s[i-1] == p[j-1] || p[j-1] == '?')
                    dp[i][j] = dp[i-1][j-1]   ;

                else if(p[j-1] == '*')
                    for(int k = 0 ; k <= i ;k++)
                       if(dp[i-k][j-1])
                       {
                           dp[i][j] = 1;
                           break ;
                       }
            }

        return dp[n][m] ;
    }
};,11,https://leetcode.com/problems/wildcard-matching,https://leetcode.com/problems/wildcard-matching/solutions/4199028/simple-and-clear-approach/

class Solution {
public:
    vector<vector<string> > sols; // 2D vector of strings to store the solutions
    vector<vector<string>> solveNQueens(int n) {    
	    vector<string> board(n, string(n, '.'));  // creating an empty board
	    solve(board, 0); // calling the recursive function
	    return sols; 
    }
    bool isSafe(vector<string>& board, int row, int col) {
	    int n = size(board);
	    for(int i = 0; i < n; i++) {
			// checking if there is a queen in the same column
		    if(board[i][col] == 'Q') return false; 
		    // checking if there is a queen in the same diagonal (left to right)
		    if(row - i >= 0 && col - i >= 0 && board[row - i][col - i] == 'Q') return false;
		    if(row - i >= 0 && col + i <  n && board[row - i][col + i] == 'Q') return false;
		    // No need to traverse more since the lower rows below current row attribute will always be safe.
			/* if(row + i <  n && col - i >= 0 && board[row + i][col - i] == 'Q') return false;
			if(row + i <  n && col + i <  n && board[row + i][col + i] == 'Q') return false; */
	    }
	    return true;
    }
    // Recursive Function (solve) - It basically tries all possible placement of queen for the current row & recurses for it's next row
    void solve(vector<string>& board, int row) {
	// Base condition. 
    // We reached the last row, so we have a solution so we add it to the solution vector
	    if(row == size(board)) { 
		    sols.push_back(board);
		    return;
    	}            
	    // Try placing a queen on each column for a given row. 
        // Explore next row by placing Q at each valid column for the current row
	    for(int col = 0; col < size(board); col++){
		    if(isSafe(board, row, col)) {
			    board[row][col] = 'Q';    // Queen placed on a valid cell
			    solve(board, row + 1);    // Exploring next row
			    board[row][col] = '.';    // Backtracking to get all possible solutions
		    }
        }
    }
};,73,https://leetcode.com/problems/n-queens,https://leetcode.com/problems/n-queens/solutions/2107948/c-easy-explanation-w-backtracking/

class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        int maxSum = nums[0];
        int currentSum = nums[0];

        for (int i = 1; i < nums.size(); i++) {
            currentSum = max(nums[i], currentSum + nums[i]);
            maxSum = max(maxSum, currentSum);
        }

        return maxSum;
    }
