            if (i == -1 || nums[i] != nums[j]) {
                i++;
                nums[i] = nums[j];
                if (j < n-1 && nums[j] == nums[j+1]) {
                    i++;
                    nums[i] = nums[j];
                    j++;
                }
            }
        }
        return i + 1;
    }
