class Solution {
public:
    Node* connect(Node* root) {
        if(!root) return root;
        queue<Node*> q;
        q.push(root);
        while(!q.empty()) {
            int sz = q.size();
            while(sz--) {
                Node* u = q.front();
                q.pop();
                if(sz) u->next = q.front(); 
                if(u->left) q.push(u->left);
                if(u->right) q.push(u->right);
            }
        }
        return root;
    }
