class Solution {
public:
    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
        int& v = numCourses; // alias
        vector<int> adj[v];

        // building adjacency list
        for (auto& pr : prerequisites) {
            adj[pr[1]].emplace_back(pr[0]);
        }

        vector<int> indegree(v);

        for (int i = 0; i < v; i++) {
            for (auto& adjNode : adj[i]) {
                indegree[adjNode]++;
            }
        }

        queue<int> Q;
        for (int i = 0; i < v; i++) {
            if (indegree[i] == 0)
                Q.emplace(i);
        }

        int topoLen = 0;

        while (!Q.empty()) {
            int node = Q.front(); Q.pop();
            topoLen++;
            for (auto& adjNode : adj[node]) {
                if (--indegree[adjNode] == 0)
                    Q.emplace(adjNode);
            }
        }

        return topoLen == v;
    }
};,119,https://leetcode.com/problems/course-schedule,https://leetcode.com/problems/course-schedule/solutions/3843975/c-dfs-bfs-topological-sort-kahn-s-algorithm/

class Solution {
public:
    int minSubArrayLen(int tar, vector<int>& nums) {
        int summ=accumulate(nums.begin(),nums.end(),0);
        if(summ<tar){
            return 0;
        }
        int l=0,r=0;
        int sum=0;
        int mini=INT_MAX;
        int n=nums.size();
        while(r<n){
            if(sum<tar){
                sum+=nums[r];
                r++;
            }
            else{
                mini=min(mini,(int)(r-l));
                sum-=nums[l];
                l++;
            }
        }
        while(sum-nums[l]>=tar){
            sum-=nums[l];
            l++;
        }
        mini=min(mini,r-l);
        return mini;
    }
