class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        // Base case...
        if(nums == null || nums.length < 2 || k == 0)
            return false;
        int i = 0;
        // Create a Hash Set for storing previous of k elements...
        HashSet<Integer> hset = new HashSet<Integer>();
        // Traverse for all elements of the given array in a for loop...
        for(int j = 0; j < nums.length; j++) {
            // If duplicate element is present at distance less than equal to k, return true...
            if(!hset.add(nums[j])){
                return true;
            }
            // If size of the Hash Set becomes greater than k...
            if(hset.size() >= k+1){
                // Remove the last visited element from the set...
                hset.remove(nums[i++]);
            }
        }
        // If no duplicate element is found then return false...
        return false;
    }
},120,https://leetcode.com/problems/contains-duplicate-ii,https://leetcode.com/problems/contains-duplicate-ii/solutions/2463150/very-easy-100-fully-explained-java-c-python-javascript-python3-using-hashset/

class Solution {

    // Approach:
    // Using sliding window technique.
    // Traversing from left to right, we use a HashSet to store the integers that we saw.
    // If the same integer is seen again, we have found the duplicate.
    // Then, we update the window again to be within 'k' index from 'index'.

    public boolean containsNearbyDuplicate(int[] nums, int k) {
        // If k is 0, then i and j cannot be distinct.
        if (k == 0) return false;

        // Set up the HashSet.
        Set<Integer> slidingWindow = new HashSet<>();

        // Start sliding the slidingWindow to the right.
        for (int index = 0; index < nums.length; index++) {
            // Return true when found duplicates in the slidingWindow.
            if (slidingWindow.contains(nums[index]))
                return true;

            // Update the state of the window, but removing the leftmost integer and add the new integer.
            if (index >= k)
                slidingWindow.remove(nums[index - k]);

            slidingWindow.add(nums[index]);
        }
        // If successfully traverse the whole array, meaning we fail to find any integers fulfilling the conditions.
        return false;
    }
},144,https://leetcode.com/problems/contains-duplicate-ii,https://leetcode.com/problems/contains-duplicate-ii/solutions/2727210/java-explained-in-detail-simple-fast-solution-hashmap-sliding-window/

