    string getHint(string secret, string guess) {
        int x=0; int y=0;
        unordered_map<int,int> mp1;
        unordered_map<int,int> mp2;
        for (int i=0; i<guess.size(); i++){
            if (guess[i]== secret[i]){
                x++;
