module PQ
    class SaPQ
        attr_reader :sa

        def initialize
            @sa = []
        end

        def cmp(a, b)
            throw "cmp() is abstract, not implemented"
        end

        def <<(e)
            @sa.insert(sa.bsearch_index {|w| cmp(w, e) } || -1, e)
        end

        def pop
            empty? ? nil : @sa.pop
        end

        def first
            sa.last
        end

        def empty?
            sa.empty?
        end
    end
end

class MinSaPQ < PQ::SaPQ
