    def add!(l, r)
        return if l >= s1 || r >= s2 || @visited.include?([l, r])
        @pq << [n1[l], n2[r], l, r]
        @visited << [l, r]
    end

    def solve(k)
        @pq = MinSaPQ.new
        @pq << [n1.first, n2.first, 0, 0]
        @visited = Set[[0, 0]]
        k.times.inject([]) {|res, _|
            break res if @pq.empty?
            nv1, nv2, l, r = @pq.pop
            res << [nv1, nv2]
            add!(l+1, r)
            add!(l,   r+1)
            res
        }.first(k)
    end
end

