class Solution {
public:
    bool isPossible(int maxSum,vector<int>& nums,int k) {
        int n = nums.size();
        int count = 1;
        int currSum = 0;

        for(int i=0;i<n;i++) {
            if(currSum + nums[i] <= maxSum) {
                currSum += nums[i];
            }
            else {
                count++;

                if(count > k || nums[i] > maxSum)
                    return false;

                currSum = nums[i];
            }
        }


        return true;
    }

    int splitArray(vector<int>& nums, int k) {
        int n = nums.size();
        int low = *max_element(nums.begin(),nums.end());

        int high = accumulate(nums.begin(),nums.end(),0);

        int ans;

        while(low <= high) {
            int mid = low + (high-low)/2;

            if(isPossible(mid,nums,k)) {
                ans = mid;
                high = mid-1;
            }
            else {
                low = mid+1;
            }
        }


        return ans;
    }
