        int oc = size(strs[i]) - zc;
        if(m - zc >= 0 && n - oc >= 0){
            return dp[i][m][n] = max(1 + dfs(i+1,m-zc,n-oc,strs) , dfs(i+1,m,n,strs));
        }
        else{
            return dp[i][m][n] = dfs(i+1,m,n,strs);
        }
    }
