let findRotateSteps = (ring, key, m = new Map()) => {
    let M = ring.length,
        N = key.length;
    let steps = (i, k) => {
        let x = Math.abs(i - k);
        return Math.min(x, M - x); // ⭐️ minimum x steps to rotate the ring from i..k (🚫 without wrap-around, ✅ with wrap-around)
    };
    let dp = [...Array(M)].map(_ => Array(N + 1).fill(Infinity)); // 🤔 memo
    for (let i = 0; i < M; ++i)
        dp[i][N] = 0; // 🛑 base case
    for (let j = N - 1; 0 <= j; --j)    // key j
        for (let i = 0; i < M; ++i)     // cur i
            for (let k = 0; k < M; ++k) // pre i (optimal k-th value is found as the recursive stack unwinds)
                if (ring[k] == key[j])
                    dp[i][j] = Math.min(dp[i][j], 1 + steps(i, k) + dp[k][j + 1]); // 🎯 min steps to reach key[j] from each ring[i] is the min steps to reach key[j + 1] from ring[k], 🔍 find optimal k via exhaustive search
    return dp[0][0]; // 🚀 when the ring starts at i = 0 (ie. index 0 is aligned with the 12:00 direction of the ring) return the min steps to construct key[j = 0..N - 1]
};,177,https://leetcode.com/problems/freedom-trail,https://leetcode.com/problems/freedom-trail/solutions/1147789/the-art-of-dynamic-programming/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<int> largestValues(TreeNode* root) {
        vector<int> result;
        if(root == nullptr) return result;
        queue<TreeNode*> bfs;
        bfs.push(root);

        while(!bfs.empty()){
            int sz = bfs.size();
            int maxi = INT_MIN;
            while(sz--){
                TreeNode* temp = bfs.front();
                bfs.pop();
                if(temp->left != nullptr){
                    bfs.push(temp->left);
                }
                if(temp->right != nullptr){
                    bfs.push(temp->right);
                }
                maxi = max(maxi, temp->val);
            }
            result.push_back(maxi);

        }

        return result;
    }
};,105,https://leetcode.com/problems/find-largest-value-in-each-tree-row,https://leetcode.com/problems/find-largest-value-in-each-tree-row/solutions/4201777/easy-bfs-solution-with-intuition-explanation-and-visualization/

class Solution {
public:
    vector<int> ans;

    vector<int> largestValues(TreeNode* root) {
        dfs(root, 0);
        return ans;
    }

    void dfs(TreeNode* node, int depth) {
        if (node == nullptr) {
            return;
        }

        if (depth == ans.size()) {
            ans.push_back(node->val);
        } else {
            ans[depth] = max(ans[depth], node->val);
        }

        dfs(node->left, depth + 1);
        dfs(node->right, depth + 1);
    }
};
