class Solution {
public:

    // this question can be solved using finding the number of         connected components i.e do BFS/DFS on each node and the number of times you are able to do the BFS/DFS will be your answer and I have done this question in that way

    // But this question can be also solved using DSU i.e just put those nodes in same group which are connected to each others and the total number of leaders will be your ans;

    // Given below is the code in which I have solved this question using DSU


    vector<int> par;
    vector<int> rank;

    int find(int a){
        if(par[a]==a) return a;
        else return par[a] = find(par[a]);
    }

    void Union(int a, int b){
        a = find(a);
        b = find(b);
        if(a==b) return;

        if(rank[a]>rank[b]){
            par[b] = a;
            rank[a]++;
        }else{
            par[a] = b;
            rank[b]++;
        }
    }
    int findCircleNum(vector<vector<int>>& arr) {

        int n = arr.size();
        rank.resize(n,0);
        par.resize(n,0);

        for(int i=0; i<n; i++){
            par[i] = i;
        }

        for(int i=0; i<n; i++){
            for(int j=0; j<n; j++){
                if(i!=j && arr[i][j]==1){
                    Union(i,j);
                }
            }
        }

        int ans = 0;
        for(int i=0; i<n; i++){
            if(par[i]==i) ans++;
        }
