            for(int j=i;j<s.length();j++){
                if(j-(j-i)==0){
                     dp[j-i][j]=true;
                     c++;
                }
                else if(j-(j-i)==1){
                    if(s.charAt(j)==s.charAt(j-i)){ 
                        dp[j-i][j]=true;
                    c++;
                    }
                    else dp[j-i][j]=false;
                }
                else{
if(s.charAt(j)==s.charAt(j-i)&&dp[j-i+1][j-1]==true){ 
