class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        int n=arr.length,i,dif; 
        List<Integer> list = new ArrayList<Integer>();
        int min=Integer.MAX_VALUE,index=-1;

        for(i=0;i<n;i++){ 
            dif=Math.abs(arr[i]-x);
            if(min>dif){
                min=dif;
                index=i;
            }
        }

        int left=index,right=index+1;
        for(i=0;i<k;i++){
            if(left>=0 && ((right<n && Math.abs(arr[left]-x)<=Math.abs(arr[right]-x)) || right==n))
                left--;
            else right++;
        }
        for(i=left+1;i<right;i++)
            list.add(arr[i]);
        return list;
    }
