class Union
{
public:
   vector<int> parent , rank ; 
   Union(int n )
   {
      rank.resize(n+1,0);
      parent.resize(n+1,0);
      for(int i = 0 ; i<=n;i++)
      parent[i] = i; 

   }

   int find(int node )
   {
       if(parent[node] == node)
       return node ; 
       else return parent[node] = find(parent[node]);
   }

   void merge(int a, int b)
   {
       int up_a = find(a);
       int up_b = find(b);
       if(up_a==up_b)
       return ; 
       if(rank[up_a]>rank[up_b])
       {
          parent[up_b] = up_a; 
       }
       else if(rank[up_a]<rank[up_b])
       {
          parent[up_a] = up_b; 
       }
       else 
       {
           parent[up_a] = up_b;
           rank[up_b]++;

       }
   }

};
class Solution {
