    vector<int> findRedundantConnection(vector<vector<int>>& edges) 
    {  int x = - 1 , y = -1 ;
       Union ds(edges.size());
       for(int i = 0;i<edges.size();i++ )
       {
           if(ds.find(edges[i][0])==ds.find(edges[i][1]))
           {
               x = edges[i][0];
               y = edges[i][1];
           }
           else ds.merge(edges[i][0],edges[i][1]);
       } 
       return {x,y};
    }
