class Solution {
public:
    vector<vector<double>> dp;

    double knight_loop(int n, int k, int r, int c) {
        if (k == 0) return 1;
        for (int move = 1; move <= k; move++) { 
            vector<vector<double>> new_dp(n, vector<double>(n)); // Initialize a new dp table for each iteration
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    double prob = 0;
                    for (auto [a, b] : moves) {
                        int r1 = i + a, c1 = j + b;
                        if (r1 >= 0 && r1 < n && c1 >= 0 && c1 < n) {
                            prob += 0.125 * dp[r1][c1];
                        }
                    }
                    new_dp[i][j] = prob;
                }
            }
            dp = new_dp; // Update dp table for the next iteration
        }
        return dp[r][c];
    }

    double knightProbability(int n, int k, int row, int column) {
        dp.assign(n, vector<double>(n, 1));
        return knight_loop(n, k, row, column);
    }
