class TrieNode {
    private final int ALPHABET_SIZE = 26;
    TrieNode[] children;
    boolean isEnd;
    TrieNode() {
        children = new TrieNode[ALPHABET_SIZE];
        isEnd = false;
    }
}

class Trie {
    private final TrieNode root = new TrieNode();
    private int maxLength = 0;
    private String longestStr = "";
    Trie(){}

    public void insert(String word) {
        TrieNode current = root;
        for (Character c: word.toCharArray()) {
            TrieNode child = current.children[c - 97];
            if(child == null) {
                child = new TrieNode();
                current.children[c - 97] = child;
            }
            current = child;
        }
        current.isEnd = true;
    }

    public String getLongestStr() {
        for (int i = 0; i < root.children.length; i++) {
            if (root.children[i] != null) {
                dfs("" + ((char) (i + 97)), root.children[i]);
            }
        }
        return longestStr;
    }

    private void dfs(String str, TrieNode node) {
        if(!node.isEnd) return;
        if(str.length() > maxLength) {
            maxLength = str.length();
            longestStr = str;
        }
        for (int i = 0; i < node.children.length; i++) {
            if(node.children[i] != null) {
                dfs(str + ((char) (i + 97)), node.children[i]);
            }
        }
    }
}

class Solution {
    public String longestWord(String[] words) {
        Trie trie = new Trie();
        for (String word: words) trie.insert(word);
        return trie.getLongestStr();
    }
