public class Solution {
    public int PeakIndexInMountainArray(int[] arr) {
        int left = 0;
        int right = arr.Length - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;

            if (arr[mid] < arr[mid + 1]) {
                // We are on the ascending slope, move right
                left = mid + 1;
            } else {
                // We are on the descending slope or at the peak, move left
                right = mid;
            }
        }

        // At this point, left and right will be pointing to the peak element
        return left;
    }
