public:
    static constexpr int MOD = 1'000'000'007;

    int profitableSchemes(int n, int minProfit, vector<int>& group, vector<int>& profit) {
        vector<vector<int>> dp(n+1, vector<int>(minProfit+1));
        auto new_dp=dp;
        for(int i = 0; i<=n; i++) {
            dp[i][0] = 1;
        }
        for(int i = (int)group.size()-1; i>= 0; i--) {
            for(int j = 0; j<=n; j++) {
                for(int p = 0; p <= minProfit; p++) {
                    int not_taken = dp[j][p];
                    int taken = 0;
                    if(group[i] <= j) {
                        taken = dp[j - group[i]][max(0, p - profit[i])];   
                    }
                    new_dp[j][p] = (taken + not_taken) % MOD;
                }
            }
            swap(dp, new_dp);

        }
        return dp[n][minProfit];
    }
};,80,https://leetcode.com/problems/profitable-schemes,https://leetcode.com/problems/profitable-schemes/solutions/3439748/c-java-python-dynamic-programming-knapsack/

class Solution {
    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {

        int mod = 1000000007;
        int[][][] dp = new int[group.length + 1][n + 1][minProfit + 1];
        dp[0][0][0] = 1;
        for (int i = 1; i <= group.length; i++) {
            int members = group[i - 1], earn = profit[i - 1];
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= minProfit; k++) {
                    dp[i][j][k] = dp[i - 1][j][k];
                    if (j >= members) {
                        dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j - members][Math.max(0, k - earn)]) % mod;
                    }
                }
            }
        }
        int res = 0;
        for (int j = 0; j <= n; j++) {
            res = (res + dp[group.length][j][minProfit]) % mod;
        }
        return res;
    }
},80,https://leetcode.com/problems/profitable-schemes,https://leetcode.com/problems/profitable-schemes/solutions/3439748/c-java-python-dynamic-programming-knapsack/

class Solution {
public:
    int numRescueBoats(vector<int>& people, int limit) {
        int boatCount = 0;
        sort(people.begin(), people.end());

        int left = 0;
        int right = people.size() - 1;

        while(left <= right){
            int sum = people[left] + people[right];
            if(sum <= limit){
                boatCount++;
                left++;
                right--;
            }
            else{
                boatCount++;
                right--;
            }
        }
        return boatCount;
    }
};,3,https://leetcode.com/problems/boats-to-save-people,https://leetcode.com/problems/boats-to-save-people/solutions/1877945/java-c-a-very-easy-explanation-trust-me/

