class Solution {
public:
    vector<int> threeEqualParts(vector<int>& arr) 
    {
        int n = arr.size() ;
        vector<int> one ;
        for(int i = 0 ; i < n ; i++)
        {
            if(arr[i])
            {
                one.push_back(i) ;
            }
        }
        int cnt = one.size() ;
        if(cnt == 0)
        {
            return {0 , n - 1} ;
        }
        if(cnt%3)          //IF NUMBER OF ONES IS NOT A MULTIPLE OF 3
        {
            return {-1 , -1} ;
        }
        int s = one[0] , t = one[cnt/3] , u = one[(cnt/3)*2] ;
        while(u < n && arr[s] == arr[t] && arr[s] == arr[u])
        {
            s++ ;
            t++ ;
            u++ ;
        }
        if(u == n)
        {
            return {s - 1 , t} ;
        }
        return {-1 , -1} ;
    }
};,155,https://leetcode.com/problems/three-equal-parts,https://leetcode.com/problems/three-equal-parts/solutions/1343092/three-equal-parts-c-easy-solution-with-approach/

var numSubarraysWithSum = function (a, t) {
    let s = 0; // sum
    let m = new Map([[0, 1]]); // prev sum & count
    let tot = 0;
    for (let e of a) {
        s += e;
        let diff = s - t; // must be some other prev sum
        tot += m.get(diff) || 0;
        m.set(s, (m.get(s) || 0) + 1);
    }
    return tot;
