class Solution {
    public void dfs(int[][] graph,int i,int j)
    {
        if(i<0||j<0||i>=graph.length||j>=graph[0].length||graph[i][j]==0||graph[i][j]==2)
            return ;
        graph[i][j]=2;
        dfs(graph,i+1,j);
        dfs(graph,i,j+1);
        dfs(graph,i-1,j);
        dfs(graph,i,j-1);  
    }
    public int shortestBridge(int[][] grid) {
        int firstX=-1,firstY=-1;
        for(int i=0;i<grid.length;i++)
        {
            for(int j=0;j<grid[0].length;j++)
            {
                if(grid[i][j]==1)
                {
                    firstX=i;
                    firstY=j;
                    break;
                }
            }
        }
        dfs(grid,firstX,firstY);
        Queue<Pair<Integer,Integer>> q=new LinkedList();
        for(int i=0;i<grid.length;i++)
        {
            for(int j=0;j<grid[0].length;j++)
            {
                if(grid[i][j]==2)
                {
                    q.offer(new Pair(i,j));
                }
            }
        }
        int lev=0;
        while(!q.isEmpty())
        {
            lev++;
            int size=q.size();
            while(size-->0)
            {
                Pair<Integer,Integer> fr=q.poll();
                int [] dx=new int[] {-1,0,1,0};
                int [] dy=new int []{0,1,0,-1};
                for(int i=0;i<4;i++)
                {
                    int new_i=fr.getKey()+dx[i],new_j=fr.getValue()+dy[i];
                    if(new_i>=0&&new_j>=0&&new_i<grid.length&&new_j<grid[0].length)
                    {
                        if(grid[new_i][new_j]==0)
                        {
                            grid[new_i][new_j]=2;
                            q.offer(new Pair(new_i ,new_j));
                        }
                         if(grid[new_i][new_j]==1)
                             return lev-1;
                    }
                }
            }
        }
        return 0;
    }
},44,https://leetcode.com/problems/shortest-bridge,https://leetcode.com/problems/shortest-bridge/solutions/3548735/934-shortest-bridge-java/

class Solution {
public:
    static const int MOD = 1e9 + 7;
    int knightDialer(int n) {
        // Initialize an array to store the possible positions of the knight on the phone pad
        vector<long long> curPos(10, 1);

        // Loop through the number of jumps required
        for (int jump = 2; jump <= n; jump++) {
            // Create a new array to store the updated positions after each jump
            vector<long long> newPos(10);

            // Calculate the new positions based on the valid knight moves
            newPos[0] = (curPos[6] + curPos[4]) % MOD;
            newPos[1] = (curPos[6] + curPos[8]) % MOD;
            newPos[2] = (curPos[7] + curPos[9]) % MOD;
            newPos[3] = (curPos[4] + curPos[8]) % MOD;
            newPos[4] = (curPos[0] + curPos[3] + curPos[9]) % MOD;
            newPos[5] = 0;  // Knight cannot move to position 5
            newPos[6] = (curPos[0] + curPos[1] + curPos[7]) % MOD;
            newPos[7] = (curPos[2] + curPos[6]) % MOD;
            newPos[8] = (curPos[1] + curPos[3]) % MOD;
            newPos[9] = (curPos[2] + curPos[4]) % MOD;

            // Update the current positions array for the next iteration
            curPos = newPos;
        }

        // Calculate the total count of distinct phone numbers
        long long totalCount = 0;
        for (int i = 0; i < 10; i++) {
            totalCount = (totalCount + curPos[i]) % MOD;
        }

        return totalCount;
    }
};,148,https://leetcode.com/problems/knight-dialer,https://leetcode.com/problems/knight-dialer/solutions/4333942/easy-iterative-approach-explained-intuition/

class Solution {
public: 
    int Mod=1e9+7;
    int solve(int i, int j, vector<vector<int>>& phone, int curr_jumps, int jumps,vector<vector<int>>& dp){

        if(curr_jumps==jumps)return 1;
        if(dp[phone[i][j]][curr_jumps]!=-1)return dp[phone[i][j]][curr_jumps];

        int Drow[8]={1,1,-1,-1,2,2,-2,-2};
        int Dcol[8]={2,-2,2,-2,-1,1,-1,1};
        int sum=0;
        for(int k=0; k<8; k++){
            int nRow=i+Drow[k];
            int nCol=j+Dcol[k];
            if(nRow>=0 && nRow<4 && nCol>=0 && nCol<3 && phone[nRow][nCol]!=INT_MAX){
                int temp=solve(nRow,nCol,phone,curr_jumps+1,jumps,dp);
                sum= (sum+temp)%Mod;
            }
        }
        return dp[phone[i][j]][curr_jumps]=sum%Mod;

    }
    int knightDialer(int n) {
        if(n==1)return 10;
        vector<vector<int>> phone(4,vector<int>(3,0));
        phone[0][0]=1;
        phone[0][1]=2;
        phone[0][2]=3;
        phone[1][0]=4;
        phone[1][1]=5;
        phone[1][2]=6;
        phone[2][0]=7;
        phone[2][1]=8;
        phone[2][2]=9;
        phone[3][0]=INT_MAX;
        phone[3][1]=0;
        phone[3][2]=INT_MAX;
        int ans=0;
        vector<vector<int>> dp(10,vector<int>(n,-1));


        for(int i=0; i<4; i++){
            for(int j=0; j<3; j++){
                if(phone[i][j]==INT_MAX)continue;
                else {
                    ans+= solve(i,j,phone,1,n,dp);
                    ans=ans%Mod;
                }
            }
        }
        return ans;
    }
};,188,https://leetcode.com/problems/knight-dialer,https://leetcode.com/problems/knight-dialer/solutions/4333745/4-solutions-memoization-1-memoization-2-tabulation-1-tabulation-1-tc-o-n-tc-o-n/

