/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<vector<int>> verticalTraversal(TreeNode* root) {

       //Syntax of Map -> (vertical -> level -> Node)
       map<int,map<int,multiset<int>>> mp;

       //Syntax of the queue -> ({node,{vertical,level}})
       queue<pair<TreeNode*,pair<int,int>>> q;


       q.push({root,{0,0}});


       while(!q.empty()) {
           auto p = q.front();
           q.pop();

           TreeNode* node = p.first;

           int x = p.second.first;
           int y = p.second.second;

           mp[x][y].insert(node->val);

           if(node->left) {
               q.push({node->left,{x-1,y+1}});
           }

           if(node->right) {
               q.push({node->right,{x+1,y+1}});
           }
       } 


       vector<vector<int>> ans;

       for(auto it : mp) {
           vector<int> col;

           for(auto p : it.second) {
               col.insert(col.end(),p.second.begin(),p.second.end());
           }

           ans.push_back(col);
       }


       return ans;
    }
};,90,https://leetcode.com/problems/vertical-order-traversal-of-a-binary-tree,https://leetcode.com/problems/vertical-order-traversal-of-a-binary-tree/solutions/3974305/simple-sol-full-explanation/

