class Solution {
    static int n;
    static int m;
    static int dir[][] = {{0,1},{0,-1},{-1,0},{1,0}};

    static void bfs(Queue<int[]> q, int arr[][]){

        while(q.size()!=0){
            int a[] = q.remove();
            int x = a[0];
            int y = a[1];
            arr[x][y] = 0;

            for(int i=0; i<4; i++){
                int nx = x+dir[i][0];
                int ny = y+dir[i][1];

                if(nx>=0 && nx<n && ny>=0 && ny<m && arr[nx][ny]==1){
                    arr[nx][ny] = 0;
                    q.add(new int[]{nx,ny});
                }
            }
        }
    }

    public int numEnclaves(int[][] arr) {
        n = arr.length;
        m = arr[0].length;

        Queue<int[]> q = new LinkedList<>();

        for(int i=0; i<n; i++) if(arr[i][0]==1) q.add(new int[]{i,0});
        for(int i=0; i<n; i++) if(arr[i][m-1]==1) q.add(new int[]{i,m-1});

        for(int j=1; j<m-1; j++) if(arr[0][j]==1) q.add(new int[]{0,j});
        for(int j=1; j<m-1; j++) if(arr[n-1][j]==1) q.add(new int[]{n-1,j});

        bfs(q,arr);
        int ans = 0;
        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if(arr[i][j]==1) ans++;
            }
        }
        return ans;
    }
},85,https://leetcode.com/problems/number-of-enclaves,https://leetcode.com/problems/number-of-enclaves/solutions/4443197/easy-java-solution-multi-source-bfs/

class Solution {
public:

    int dp[104][104];
    int solve(int i, vector<vector<int>>& clips, int mx, int time){
        if(mx >= time) return 0;
        if(i >= clips.size()){
            return INT_MAX;
        }
        if(dp[i][mx] != -1) return dp[i][mx];
        if(clips[i][0] <= mx){
            int temp = solve(i+1,clips,max(mx,clips[i][1]),time);
            return dp[i][mx] = min(temp == INT_MAX ? INT_MAX : temp+1 , solve(i+1,clips,mx,time));
        }
        return dp[i][mx] = INT_MAX;
    }

    int videoStitching(vector<vector<int>>& clips, int time) {
        int n = clips.size();
        sort(clips.begin(),clips.end());
        if(clips[0][0] != 0) return -1;
        memset(dp,-1,sizeof(dp));
        int ans = solve(0,clips,0,time);
        return ans == INT_MAX ? -1 : ans;
    }
