class StreamChecker {
    unordered_set<int> suffixHash, wordHash;
    string queryStream = "";
	// returns rolling hash after adding a new character c
    int rollingHash(long& hash, long& p_pow, char c, int mod = 1e9+7) {
        p_pow = (p_pow * 31) % mod;
        return hash = (hash + (c-'a'+1) * p_pow) % mod;
    }
public:    
    StreamChecker(vector<string>& words) { 
        for(auto& w : words) {
            long hash = 0, p_pow = 1;
            for(int i = size(w)-1; ~i; i--) 
                suffixHash.insert(rollingHash(hash, p_pow, w[i]));                          // insert all suffix hashes of each word
            wordHash.insert(hash);                                                          // complete word hash
        }
    }
    bool query(char c) {
        queryStream += c;
        for(long i = size(queryStream)-1, hash = 0, p_pow = 1; ~i; i--)             
            if(!suffixHash.count(rollingHash(hash, p_pow, queryStream[i]))) return false;   // check if same suffix hash exists in suffixHash set.
            else if(wordHash.count(hash)) return true;                                      // check if there's a word with same hash

        return false;
    }
};,63,https://leetcode.com/problems/stream-of-characters,https://leetcode.com/problems/stream-of-characters/solutions/1610834/c-python-3-simple-solution-w-explanation-hashset-trie-rolling-hash/

class Solution {
public:

    int col;
    int initialCol;
    vector<pair<int,int>> ans;

    void helper(vector<vector<int>> &arr, int r, int c){
        int n = arr.size();
        int m = arr[0].size();
        if(r<0 || c<0 || r>=n || c>=m || arr[r][c]!=initialCol) return;

        arr[r][c] = -col;  // to distinguish btw colors
        helper(arr,r,c+1);
        helper(arr,r,c-1);
        helper(arr,r+1,c);
        helper(arr,r-1,c);

        // Backtracking

        // checking if it was boundary color or not

        if(!(r==0 || c==0 || r==n-1 || c==m-1 || arr[r+1][c]!=-col || arr[r-1][c]!=-col || arr[r][c-1]!=-col || arr[r][c+1]!=-col)){
            ans.push_back({r,c});  // internal color
        }
    }
    vector<vector<int>> colorBorder(vector<vector<int>>& arr, int r, int c, int color) {
        col = color;
        initialCol = arr[r][c];

        if(col==initialCol) return arr;
        helper(arr,r,c);
        for(auto p : ans){
            int i = p.first;
            int j = p.second;
            arr[i][j] = initialCol;   // retaining the color of internal node
        }

        for(int i=0; i<arr.size(); i++){
            for(int j=0; j<arr[0].size(); j++){
                if(arr[i][j]<0) arr[i][j] = col;  // boundary color
            }
        }

        return arr;
    }
};,85,https://leetcode.com/problems/coloring-a-border,https://leetcode.com/problems/coloring-a-border/solutions/4287843/easy-c-solution/

