class Solution {
public:
    int dp[31][3001];
    int dfs(int i, int sum, int k, const std::vector<int>& nums) {
        if (i >= nums.size() || sum > k) {
            return abs((k - sum) - sum);
        }

        if (dp[i][sum] != -1) {
            return dp[i][sum];
        }

        int inc = dfs(i + 1, sum + nums[i], k, nums);
        int exc = dfs(i + 1, sum, k, nums);
        return dp[i][sum] = std::min(inc, exc);
    }

    int lastStoneWeightII(std::vector<int>& nums) {
        int sum = std::accumulate(nums.begin(), nums.end(), 0);
        memset(dp, -1, sizeof(dp));
        return dfs(0, 0,sum, nums);
    }
};
