            for(int j=text2.length()-1;j>=0;j--){

                    int ans;
                    if(text1[i]==text2[j])
                        ans=1+dp[i+1][j+1];
                    else
                        ans=max(dp[i][j+1],dp[i+1][j]);
                    dp[i][j]=ans;
            }
        }
        return dp[0][0];
    }
