class Solution {
public:
    const int mod = 1e9+7;
    vector<bool>dp;
    unordered_map<long long int,long long int>memo;
    int numPrimeArrangements(int n) 
    {
         dp.resize(n+1,true);  //initally considering all to be prime
         dp[0] = false;
         dp[1] = false;

         for(int i=2;i<dp.size();i++)
         {
             //if the curr num is prime
             if(dp[i] == true)
             {
                 for(int j=i+i;j<dp.size();j+=i)
                 {
                     dp[j] = false;
                 }
             }
         }
        int composite = 0;
        int prime = 0;
        for(int i=1;i<dp.size();i++)
        {
            if(dp[i] == true) prime++;
            else composite++;
        }
        //cout<<"prime = "<<prime<<endl;
        //cout<<"composite = "<<composite<<endl;

        int val1 = fact(prime)%mod;
        //cout<<"val1 = "<<val1<<endl;

        int val2 = fact(composite)%mod;
        //cout<<"val2 = "<<val2<<endl;

        int ans = (1LL * val1 * val2)%mod;
        return ans;
    }
    int fact(int num)
    {
        if(num == 1)
        return 1;

        if(num == 0)
        return 1;

        if(memo.find(num) != memo.end())
        {
            return memo[num];
        }

        return memo[num] = (1LL * num * fact(num-1))%mod;
    }

};
