class Solution {
    vector<vector<int>> ans; int t = 0;
    vector<bool> vis;
    vector<int> tin, low;
    void dfs(vector<vector<int>> &graph,int node, int par = -1){
        tin[node] = low[node] = t++;
        vis[node] = true;
        for(auto child: graph[node]){
            if(child==par) continue;
            if(vis[child]) low[node] = min(low[node],tin[child]);
            else {
                dfs(graph,child,node);
                low[node] = min(low[node],low[child]);
                if(low[child]>tin[node]) ans.push_back({node,child});
            }
        }
    }

