class Solution {
public:
    int equalSubstring(string str, string tar, int maxCost) {

        int n = str.size();

        int left = 0;

        int curr_cost = 0;

        int maxi = 0;

        // apply sliding window

        for(int right = 0; right < n; right++)
        {
            // add the cost into curr_cost

            curr_cost += abs(str[right] - tar[right]);

            // shrink the window from left to decrement the curr_cost, to make it within range

            while(left <= right && curr_cost > maxCost)
            {
                curr_cost -= abs(str[left] - tar[left]);

                left++;
            }

            // update maxi

            maxi = max({maxi, right - left + 1});
        }

        return maxi;
    }
};,23,https://leetcode.com/problems/get-equal-substrings-within-budget,https://leetcode.com/problems/get-equal-substrings-within-budget/solutions/2644063/faster-easy-to-understand-c-code/

class Solution {
public:
    int equalSubstring(string s, string t, int maxCost) 
    {
        vector<int> prefixDiffSum(s.length()+1,0);
        int Max=0;
        for(int i=1;i<s.length()+1;i++)
        {
            prefixDiffSum[i]=prefixDiffSum[i-1]+abs(s[i-1]-t[i-1]);   //Stores sum of differences from begining till i.
            Max=max(Max,i-(int)(lower_bound(prefixDiffSum.begin(),prefixDiffSum.begin()+i+1,prefixDiffSum[i]-maxCost)-prefixDiffSum.begin()));         //Binary search to find start of the window that holds sum<=maxCost and ends with i.
        }
        return Max;
    }
