class Solution {
public:
    int dx[4]={-1,0,1,0};
    int dy[4]={0,1,0,-1};
    void dfs(int i,int j,int m,int n,vector<vector<int>> &grid)
    {
        if(i<0 or j<0 or i>=m or j>=n or grid[i][j]==1)
            return;
        grid[i][j]=1;
        for(int k=0;k<4;k++)
        {
            int x=i+dx[k];
            int y=j+dy[k];
            dfs(x,y,m,n,grid);
        }
        return;
    }
    int closedIsland(vector<vector<int>>& grid) {
        int m=grid.size();
        int n=grid[0].size();
        int cnt=0;
        queue<pair<int,int>> q;
        for(int i=0;i<m;i++)
        {
            for(int j=0;j<n;j++)
            {
                if((i==0 or i==m-1 or j==0 or j==n-1)  and grid[i][j]==0)
                {
                     q.push({i,j});
                   // cout<<i<<" "<<j<<endl;
                    grid[i][j]=1;
                }
            }
        }
        while(!q.empty())
        {
            int x=q.front().first;
            int y=q.front().second;
            q.pop();
            for(int k=0;k<4;k++)
            {
                int newx=x+dx[k];
                int newy=y+dy[k];
                if(newx<0 or newy<0 or newx>=m or newy>=n or grid[newx][newy]==1)
                    continue;
                grid[newx][newy]=1;
                q.push({newx,newy});
            }
        }
       for(int i=0;i<m;i++)
       {
           for(int j=0;j<n;j++)
           {
               if(grid[i][j]==0)
               {
                   dfs(i,j,m,n,grid);
                   cnt++;
               }
           }
       }
     return cnt;
    }
};,129,https://leetcode.com/problems/number-of-closed-islands,https://leetcode.com/problems/number-of-closed-islands/solutions/3385192/c-most-easy-solution-using-bfs-and-dfs/

class Solution {

    static List<List<Pair>> combinations;
    static List<Pair> allPairs;

    public int maxScoreWords(String[] words, char[] letters, int[] score) {
        int[] points = new int[words.length];
        //scores of each word
        List<Pair> list = new ArrayList<>();
        for (int i = 0; i < words.length; i++) {
            for (int j = 0; j < words[i].length(); j++) {
                int index = words[i].charAt(j) - 97;
                points[i] += score[index];
            }
            Pair pair = new Pair(words[i], points[i]);
            list.add(pair);
        }
        allPairs = list;
        combinations = new ArrayList<>();
		//using the loop below to find all combinations of words and different size of these combinations
        for (int i = 0; i < list.size(); i++) {
            findCombination(i, new ArrayList<>());
        }

        int[] finalScores = new int[combinations.size()];
        for (int k = 0; k < combinations.size(); k++) {
            String lettersString = new String(letters);
            String lettersCheck = new String(letters);
            List<Pair> listTemp = combinations.get(k);
            int scoreFinal = 0;
			//finding score of each combination
            for (int i = 0; i < listTemp.size(); i++) {
                Pair pair = listTemp.get(i);
                boolean fullyContains = true;
                lettersCheck = new String(lettersString);
                for (int j = 0; j < pair.word.length(); j++) {
                    if (!lettersCheck.contains(pair.word.charAt(j) + "")) {
                        fullyContains = false;
                        break;
                    }
                    lettersCheck = lettersCheck.replaceFirst(pair.word.charAt(j) + "", "");
                }
                if (!fullyContains) {
                    continue;
                }
                for (int j = 0; j < pair.word.length(); j++) {
                    lettersString = lettersString.replaceFirst(pair.word.charAt(j) + "", "");
                }
                scoreFinal += pair.score;
            }
            finalScores[k] = scoreFinal;
        }

        int max = 0;
		//finding max score out of all scores of combinations
        for (int i = 0; i < finalScores.length; i++) {
            if (max < finalScores[i]) {
                max = finalScores[i];
            }
        }
        return max;
    }
    //use this method to find different combinations of words starting from idxStart
    private void findCombination(int idxStart, List<Pair> list) {
        if (idxStart >= allPairs.size()) {
            combinations.add(new ArrayList<>(list));
            return;
        }
        list.add(allPairs.get(idxStart));
        for (int i = idxStart + 1; i <= allPairs.size(); i++) {
            findCombination(i, list);
        }
        list.remove(list.size() - 1);
    }

    class Pair {
        String word;
        int score;

        public Pair(String word, int score) {
            this.word = word;
            this.score = score;
        }
    }
