class Solution {
public:
    const int mod=1e9+7;
    vector<vector<int>> dp;
       int f(int steps, int i, int n) {//(remaining moves, index, n)
        if (steps==0) 
            return (i==0) ? 1 : 0;

        if (dp[steps][i]!= -1) 
            return dp[steps][i];

        long long ans=f(steps-1, i, n) %mod;//stay

        // Move to the right 
        if (i<n-1) 
            ans= (ans+f(steps-1, i+1, n))%mod;

        // Move to the left 
        if (i>0) 
            ans = (ans+f(steps-1, i-1, n))%mod;

        return dp[steps][i]=ans;
    }

    int numWays(int steps, int arrLen) {
        int n=min(steps/2+1, arrLen);//maximial position can reached
        dp.assign(steps+1, vector<int>(n+1, -1));
        return f(steps, 0, n);
    }
};,49,https://leetcode.com/problems/number-of-ways-to-stay-in-the-same-place-after-some-steps,https://leetcode.com/problems/number-of-ways-to-stay-in-the-same-place-after-some-steps/solutions/4169514/2ms-beats-99-57-c-recursive-dp-iterative-dp-with-optimized-sc-with-note-on-motzkin-numbers/

class Solution {
public:
    int countSquares(vector<vector<int>>& mat) {
        int n = mat.size();
        int m = mat[0].size();
        int res = 0;
        vector<vector<int>> dp(n,vector<int>(m,0));

        for(int i=0;i<n;i++)
        {
            if(mat[i][0] == 1){
                dp[i][0] = 1;
                res++;
            }
        }

        for(int i=1;i<m;i++)
        {
            if(mat[0][i] == 1){
                dp[0][i] = 1;
                res++;
            }
        }



        for(int i=1;i<n;i++)
        {
            for(int j=1;j<m;j++)
            {
                if(mat[i][j] == 1){
                    dp[i][j] = 1+ min({dp[i][j-1],dp[i-1][j-1],dp[i-1][j]});
                }
                    res+=dp[i][j];                

            }
        }

        return res;
    }
