class CombinationIterator {
public:
    CombinationIterator(string characters, int combinationLength) : 
                n(characters.size()), comb_len(combinationLength), chars(characters) {
        bitmask = (1 << n) - 1;
    }

    string next() {
        while (bitmask >= 0 && countSet(bitmask) != comb_len) bitmask--;

        string res = "";
        for (int i = 0; i < n; i++) {
            if (bitmask & (1 << (n - i - 1))) res += chars[i];
        }

        bitmask--;
        return res;
    }

    bool hasNext() {
        while (bitmask >= 0 && countSet(bitmask) != comb_len) bitmask--;
        return bitmask >= 0;
    }

    int countSet(int mask) {
        int count = 0;
        while (mask) {
            count += mask & 1;
            mask >>= 1;
        }
        return count;
    }

private:
    int bitmask, n, comb_len;
    string chars;
};,62,https://leetcode.com/problems/iterator-for-combination,https://leetcode.com/problems/iterator-for-combination/solutions/1576758/c-python-three-simple-and-clean-solutions-bitmasking-pre-calculating/

class Solution {
public:
    int removeCoveredIntervals(vector<vector<int>>& inter) {
        sort(inter.begin(),inter.end());
        int st = inter[0][0],end = inter[0][1],ans = 0;
        for(int i = 1;i<inter.size();i++)
        {
            if(inter[i][0]>=st && inter[i][1]<=end) ans++;
            else if(inter[i][0]==st && inter[i][1]>=end)
            {
                ans++;
                end = inter[i][1];
            }
            else if(inter[i][0]>=end || inter[i][1]>=end)
            {
                st = inter[i][0];
                end = max(end,inter[i][1]);
            }
        }
        return inter.size()-ans;   
    }
