class Solution {
public:
    void in(TreeNode* root,vector<int> &t){
        if(!root) return;

        in(root->left,t);
        t.push_back(root->val);
        in(root->right,t);
    }

    vector<int> getAllElements(TreeNode* root1, TreeNode* root2) {
        vector<int> t1,t2;
        in(root1,t1);
        in(root2,t2);

        vector<int> ans;

        int i = 0, j = 0;

        while(i < t1.size() && j < t2.size()){
            if(t1[i] < t2[j]){
                ans.push_back(t1[i]);
                i++;
            }
            else if(t1[i] > t2[j]){
                ans.push_back(t2[j]);
                j++;
            }
            else{
                ans.push_back(t1[i]);
                ans.push_back(t1[i]);
                i++;
                j++;
            }
        }
        while(i < t1.size()){
            ans.push_back(t1[i]);
            i++;
        }
        while(j < t2.size()){
            ans.push_back(t2[j]);
            j++;
        }
        return ans;
    }
