class Solution {
public:
    int numberOfSubstrings(string s) {
        int n = s.length();
        unordered_map <char, int> mp;
        int start = 0, end = 0;
        int count = 0;
        while (end < n) { 
            mp[s[end]]++;        
            while (mp['a'] > 0 && mp['b'] > 0 && mp['c'] > 0) {
                count += n - end; 
                mp[s[start]]--;
                start++; 
            }  
            end++; 
        }    
        return count;
    }
