class Solution {
    public int maxDiff(int num) {
        StringBuilder max = new StringBuilder(num+"");
        StringBuilder min = new StringBuilder(num+"");

        int n = max.length();
        int i=0;
        char toSet = '9';
        while(i<n && max.charAt(i) == '9'){
            i++;
        }
        char toDelete = i!=n ? max.charAt(i) : ' ';
        String maxStr = replace(max, toSet, toDelete, i, n);

        i=0;
        toSet = min.charAt(0) != '1' ? '1' : '0';
        while(i<n && (min.charAt(i) == '1' || min.charAt(i) == '0')){
            i++;
        }
        toDelete = i!=n ? min.charAt(i) : ' ';
        String minStr = replace(min, toSet, toDelete, i, n);

        return Integer.valueOf(maxStr) - Integer.valueOf(minStr);
    }

    public String replace(StringBuilder sb, char toSet, char toDelete, int idx, int n){
        while(idx!=n && toDelete!=' '){
            if(sb.charAt(idx) == toDelete)
                sb.setCharAt(idx, toSet);
            idx++;
        }
        return sb.toString();
    }
