class Solution {

    /*
        Tabulation:
        Time Complexity : O(m*n*n)
        Space Complexity : O(n*n)
    */

public:
    int dirc[3] = {-1, 0, +1};

    int cherryPickup(vector<vector<int>>& grid) {
        int m=grid.size(), n=grid[0].size();
        vector<vector<int>> prev (n, vector<int> (n, 0));

        for(int c1=0; c1<n; c1++){
            for(int c2=0; c2<n; c2++){
                prev[c1][c2] = (c1==c2) ? grid[m-1][c1] : grid[m-1][c1] + grid[m-1][c2];
            }
        }

        for(int r=m-2; r>=0; r--){
            vector<vector<int>> curr (n, vector<int> (n, 0));

            for(int c1=0; c1<n; c1++){
                for(int c2=0; c2<n; c2++){

                    int maxRes = 0;

                    for (int k1 = 0; k1 < 3; k1++)
                    {
                        for (int k2 = 0; k2 < 3; k2++)
                        {
                            if(c1+dirc[k1]>=0 && c1+dirc[k1]<n && c2+dirc[k2]>=0 && c2+dirc[k2]<n){
                                maxRes = max(maxRes, prev[c1+dirc[k1]][c2+dirc[k2]]);   
                            }
                        }
                    }

                    curr[c1][c2] += maxRes;
                    curr[c1][c2] += (c1 == c2) ? grid[r][c1] : grid[r][c1] + grid[r][c2];
                }
            }

            prev = curr;
        }

        return prev[0][n-1];
    }
};,68,https://leetcode.com/problems/cherry-pickup-ii,https://leetcode.com/problems/cherry-pickup-ii/solutions/3518692/c-both-memoization-tabulation-t-c-o-m-n-n-9-s-c-o-n-n/

