class Solution {
    public int minDistance(int[] houses, int k) {
        int n = houses.length;
        int[][] cost = new int[n][n];
        Integer[][] dp = new Integer[k + 1][n];
        Arrays.sort(houses);
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                for (int t = i; t <= j; t++) {
                    cost[i][j] += Math.abs(houses[(i + j) / 2] - houses[t]);
                }
            }
        }
        return dfs(cost, k, 0, n, dp);
    }

    private int dfs(int[][] cost, int k, int index, int n, Integer[][] dp) {
        if (k == 0 && index == n) {
            return 0;
        }
        if (k == 0 || index == n) {
            return Integer.MAX_VALUE;
        }
        if (dp[k][index] != null) {
            return dp[k][index];
        }
        int min = Integer.MAX_VALUE;
        for (int i = index; i < n; i++) {
            int next = dfs(cost, k - 1, i + 1, n, dp);
            if (next != Integer.MAX_VALUE) {
                min = Math.min(min, cost[index][i] + next);
            }
        }
        return dp[k][index] = min;
    }
