class Solution {
    public int[] runningSum(int[] nums) {
        // declare prefix array of nums length
        int[] prefix = new int[nums.length];
        // put first element if nums array into prefix sum
        prefix[0] = nums[0];
        // loop over each element in nums array
        for(int i = 1; i < nums.length; i++) {
            // calculate sum of previous sum that are in prefix array and current element of nums array
          int sum = prefix[i - 1] + nums[i];
            // put sum into prefix array at current index
          prefix[i] = sum;
        }
        // return prefix array
        return prefix;
    }
