        String ans[] = new String[n];

        for(int i=0; i<n; i++){
            if(hp.containsKey(arr[i])){
                int val = hp.get(arr[i]);
                StringBuilder s = new StringBuilder(arr[i]);
                s.append('(');
                s.append(val);
                s.append(')');

