                    val++;
                    s = new StringBuilder(arr[i]);
                    s.append('(');
                    s.append(val);
                    s.append(')');
                }
                ans[i] = s.toString();
                hp.put(s.toString(),1);
                hp.put(arr[i],val+1);
            }else{
                ans[i] = arr[i];
                hp.put(arr[i],1);
            }
        }
        return ans;
    }
