class Solution {
public:
    int getLastMoment(int n, vector<int>& left, vector<int>& right) {
        // Intution
        // The idea in here is, if there is a collision then in place of right ant we will get left ant and in the place of left ant we will get right ant. But, the affect would be exactly same. Consider the example below

        // Let n be 5

        // There are three ants two going to right, and one coming to left

        // Initial configuration

        // 1 - Ant1 2 - Ant2 3 - Empty 4 - Empty 5 - Ant3

        // After one second

        // 1 - Empty 2 - Ant1 3 - Ant2 4 - Ant3 5 - Empty

        // After two seconds

        // 1 - Empty 2 - Empty 3 - Ant1 4 - (Ant2 -> Right, Ant3 -> Left) 5 - Empty

        // One collision occured. So, now Ant2 -> Left, Ant3 -> Right

        // 1 - Empty 2 - Empty 3 - Ant2 4 - Ant1 5 - Ant3

        // If we assumed that collision won't make any change then

        // After two seconds collision affect will be

        // 1 - Empty 2 - Empty 3 - Ant3 4 - Ant1 5 - Ant2

        // So, we can clearly see that the affect of collision, is simply name changing and nothing more happens.

        // So, the question now frames to fiding the maximum times taken by ants moving to right to find the time of falling and also to the left.

        // Keeping tracks of maxLeft, minRight


        // maxLeft to find the maximum position i.e., to find the time taken by ants moving to the left

        // minRight to find maximum position i.e., to find the time taken by ants moving to the right


        int maxLeft = INT_MIN;
        for(auto &l : left) maxLeft = max(maxLeft, l);
        int minRight = INT_MAX;
        for(auto &r : right) minRight = min(minRight, r);
        if(maxLeft == INT_MIN)
            return n - minRight;
        else if(minRight == INT_MAX)
            return maxLeft;
        else return max(n - minRight, maxLeft);
    }
