class Solution:
    def minCostConnectPoints(self, points):
        n = len(points)
        edges = []

        for i in range(n):
            for j in range(i + 1, n):
                distance = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
                edges.append((distance, (i, j)))

        edges.sort()

        parent = list(range(n))
        min_cost = 0
        num_edges = 0

        for edge in edges:
            distance, u, v = edge[0], edge[1][0], edge[1][1]

            parent_u = self.find_parent(parent, u)
            parent_v = self.find_parent(parent, v)

            if parent_u != parent_v:
                parent[parent_u] = parent_v
                min_cost += distance
                num_edges += 1

                if num_edges == n - 1:
                    break

        return min_cost

    def find_parent(self, parent, node):
        if parent[node] == node:
            return node
        parent[node] = self.find_parent(parent, parent[node])
        return parent[node],7,https://leetcode.com/problems/min-cost-to-connect-all-points,https://leetcode.com/problems/min-cost-to-connect-all-points/solutions/4045876/simple-solution-kruskal-s-algorithm-with-explanation-c-java-and-python/

class ThroneInheritance {
    String kingName;
    Map<String, List<String>> map = new HashMap<>();  // for cache children;
    Map<String, Boolean> alive = new HashMap<>();
    public ThroneInheritance(String kingName) {
        this.kingName = kingName;
    }

    public void birth(String pn, String cn) {
        map.computeIfAbsent(pn, k -> new ArrayList<>());
        map.get(pn).add(cn);
    }

    public void death(String name) {
        alive.put(name, false);
    }

    public List<String> getInheritanceOrder() {
        List<String> list = getList(kingName);  //all list with alive and died
        List<String> res = new ArrayList<>();
        for (String s : list)
            if (alive.getOrDefault(s, true)) res.add(s);  // remove died
        return res;
    }

    private List<String> getList(String p) {   // recursion to get children and build the inheritance list;
        List<String> res = new ArrayList<>();
        res.add(p);
        List<String> cs = map.getOrDefault(p, new ArrayList<>());
        for (String c : cs) {
            List<String> tmp = getList(c);
            for (String cc : tmp) res.add(cc);
        }
        return res;
    }
