    for (let cy = 0 - radius; cy <= 50 + radius; ++cy) {
      let sum = 0;
      for (let [towerX, towerY, towerQualityFactor] of towers) {
        let dist = distEuclidean(cx, cy, towerX, towerY);
        if (dist <= radius) sum += Math.floor(towerQualityFactor / (1 + dist));
