        while(pq.size()!=0){
            int a[] = pq.remove();
            int x = a[1];
            int y = a[2];
            
            for(int i=0; i<4; i++){
                int nx = x+dx[i];
                int ny = y+dy[i];

                if(nx>=0 && nx<n && ny>=0 && ny<m){
                    int newdist = Math.max(a[0],Math.abs(arr[x][y]-arr[nx][ny]));
                    if(newdist<dist[nx][ny]){
                        dist[nx][ny] = newdist;
                        pq.add(new int[]{newdist,nx,ny});
                    }
                }
            }
        }
        return dist[n-1][m-1];
    }
