class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        // int[] -> [0] = position , [1] = can jump backward if val = 1, [2] = moves
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{0, 1, 0});

        Set<Integer> visitedForward = new HashSet<>();
        Set<Integer> visitedBackward = new HashSet<>();

        visitedForward.add(0);
        visitedBackward.add(0);

        Set<Integer> forbid = new HashSet<>();
        for(int pos : forbidden)
            forbid.add(pos);

        int max = a + b + Math.max(x, Collections.max(forbid));
        // int max = 6001;

        while(!queue.isEmpty()){
            int[] pos = queue.poll();
            if(pos[0] == x)
                return pos[2];

            //forward
            int forward = pos[0] + a;
            if(!visitedForward.contains(forward) && !forbid.contains(forward) && forward <= max){
                visitedForward.add(forward);
                queue.add(new int[]{forward, 1, pos[2]+1});
            }

            //backward
            int backward = pos[0] - b;
            if(!visitedBackward.contains(backward) && pos[1] == 1 && backward > 0 && !forbid.contains(backward)){
                visitedBackward.add(backward);
                queue.add(new int[]{backward, 0, pos[2]+1});
            }
        }
        return -1;
    }
