class Solution {
    private Integer[][] memo;
    public int stoneGameVII(int[] stones) {
        memo = new Integer[stones.length][stones.length];
        int sum = 0;
        for(int e : stones)
            sum += e;
        return dfs(stones, 0, stones.length - 1, sum, true);//we will play as Alice to maximize the difference
    }

    private int dfs(int[] stones, int i, int j, int sum, boolean alice){
        if(i == j) return 0;

        if(memo[i][j] != null) return memo[i][j];

        if(alice){//maximize Alice's gain
            int left = sum - stones[i] + dfs(stones, i + 1, j, sum - stones[i], !alice);
            int right = sum - stones[j] + dfs(stones, i, j - 1, sum - stones[j], !alice);
            return memo[i][j] = Math.max(left, right);
        }
         // minimize Bob's gain
        int left = dfs(stones, i + 1, j, sum - stones[i], !alice) - (sum - stones[i]);
        int right = dfs(stones, i, j - 1, sum - stones[j], !alice) - (sum - stones[j]);
        return memo[i][j] = Math.min(left, right);
    }
