class Solution {
public:
    int maxValue(vector<vector<int>>& e, int k) {
        vector<int> s;
        for(auto i : e) s.push_back(i[0]);
        sort(s.begin(), s.end()); // Sort the start times

        sort(e.begin(), e.end(), [](const vector<int>& a, const vector<int>& b){
           return a[0] < b[0]; 
        }); // Sort the events based on start times

        vector<vector<int>> dp(e.size()+1, vector<int>(k+1, 0)); // Create a 2D vector for dynamic programming

        int n = e.size();
        for(int idx = n-1; idx >= 0; idx--){
            for(int j = 1; j <= k; j++){
                int ntake = dp[idx+1][j]; // Don't take the current event
                int nxt = upper_bound(s.begin(), s.end(), e[idx][1]) - s.begin(); // Find the next event whose start time is after the current event's end time
                int take = e[idx][2] + dp[nxt][j-1]; // Take the current event and add its value to the maximum value obtained from the next event
                dp[idx][j] = max(take, ntake); // Choose the maximum value between taking and not taking the current event
            }
        }
        return dp[0][k]; // Return the maximum value for k events starting from the first event
    }
};
