class Solution {
public:
    int solve(vector<vector<int>>&dp, vector<vector<int>>& events, int n, int pos, int k) {
        int i;

        if(pos >= n || k == 0)
            return 0;

        if(dp[pos][k] != -1)
            return dp[pos][k];

        for(i = pos + 1; i < n; i++)
            if(events[i][0] > events[pos][1])
                break;

       return dp[pos][k] = max(solve(dp, events, n, pos + 1, k), events[pos][2] + solve(dp, events, n, i, k - 1));

    }

    int maxValue(vector<vector<int>>& events, int k) {
        int n = events.size();
        sort(events.begin(), events.end());

        vector<vector<int>>dp(n + 1, vector<int>(k + 1, -1));

        return solve(dp, events, n, 0, k);
    }
};,80,https://leetcode.com/problems/maximum-number-of-events-that-can-be-attended-ii,https://leetcode.com/problems/maximum-number-of-events-that-can-be-attended-ii/solutions/3766741/c-dp/

class Solution {
public:
    int maximumScore(int a, int b, int c) {
        priority_queue<int> pq;
        pq.push(a);
        pq.push(b);
        pq.push(c);
        int ans = 0;
        while(pq.size()>1)
        {
            int num1 = pq.top(); pq.pop();
            int num2 = pq.top(); pq.pop();
            if(num1-1>0) pq.push(num1-1);
            if(num2-1>0) pq.push(num2-1);
            ans+=1;
        }
        return ans;
    }
