class Solution {
public:
    int m, n;
    int dfs(vector<int>& nums, vector<int>& mult, vector<vector<int>>& dp, int i, int j) {
        // i : pointer at nums
        // j : pointer at mult
        // if we have performed all operations, then return 0
        if (j == m) return 0;
        // memoizated before - return the value here
        if (dp[i][j] != INT_MIN) return dp[i][j];
        // we can either choose an integer in `nums` the start or the end of the array
        // so we try both case and take the maximum value
        // then memoize it
        return dp[i][j] = max(
            // pick from the start
            mult[j] * nums[i] + dfs(nums, mult, dp, i + 1, j + 1),
            // pick fromt the end
            mult[j] * nums[n - 1 - j + i] + dfs(nums, mult, dp, i, j + 1)
        ); 
    }
    int maximumScore(vector<int>& nums, vector<int>& multipliers) {
        n = (int) nums.size(), m = (int) multipliers.size();
		// init values that couldn't be reached. -1 will cause TLE. -2 would pass but it's not supposed to pass.
        vector<vector<int>> dp(m, vector<int>(m, INT_MIN));
        // or u can return dp[0][0] after running dfs
        return dfs(nums, multipliers, dp, 0, 0);
    }
};,158,https://leetcode.com/problems/maximum-score-from-performing-multiplication-operations,https://leetcode.com/problems/maximum-score-from-performing-multiplication-operations/solutions/2581635/leetcode-the-hard-way-explained-line-by-line/

class Solution {
    public int maximumScore(int[] nums, int[] multipliers) {

        int N = nums.length;
        int M = multipliers.length;

        // Pointer for traversing the multipliers array.
        int current = M;

        // Memoization involves saving the optimum solution from the previous operation for easy retrieval.
        // This is so that we can avoid repeating the operation, thus lowering time complexity.
        int[] maximumScore = new int[M];
        int[] memo = new int[M+1];

        // As we traverse from back to front of the multipliers array, 
        // we are also multiplying from the ends (left and right) to the center of the nums array.
        // Each iteration, we get the higher value sums of the multiplication and highest value from previous round (memo).
        // Note:
        // Imagine the first multiple (0) in the multipliers can only choose first left or right in the nums.
        // While the last multiple (M-1) in the multipliers can possibly choose 0 to M-th number from left or right nums.
		// Since choosing the first left or right number can affect the choice in the following iteration, we need to
        // record the highest scores possible starting from the last multiple (M-1), for the optimum number picking.

		// As both multipliers and nums is 1-indexed, we perform the --current and ++i, to exit the loop once reach 0.
        while (--current >= 0) {
            for (int i = 0; i <= current; ++i) {
                int left = memo[i+1] + multipliers[current] * nums[i];
                int right = memo[i] + multipliers[current] * nums[N - current + i - 1];
                maximumScore[i] = Math.max(left, right);
            }
            // Store the current round of maximumScores in the memo, for reference in the next round.
            memo = maximumScore;
        }
        return maximumScore[0];
    }
},144,https://leetcode.com/problems/maximum-score-from-performing-multiplication-operations,https://leetcode.com/problems/maximum-score-from-performing-multiplication-operations/solutions/2581586/java-solution-explained-dynamic-programming-memoization-iterative-recursive-methods/

class Solution {
public:
    vector<vector<int>> dp;
    int solve(vector<int>& nums, vector<int>& mul,int idx,int start)
    {
        if(idx==mul.size())
            return 0;
        if(dp[start][idx]!=INT_MIN)
            return dp[start][idx];
        int left=solve(nums,mul,idx+1,start+1)+nums[start]*mul[idx];
        int right=solve(nums,mul,idx+1,start)+nums[nums.size()-1-(idx-start)]*mul[idx];
        //end=nums.size()-1-(idx-start);
        return dp[start][idx]=max(left,right);
    }
    int maximumScore(vector<int>& nums, vector<int>& mul) 
    {
        int m=mul.size();
        dp.resize(m+1,vector<int>(m+1,INT_MIN));
        return solve(nums,mul,0,0);
    }
};

