class Solution {
    public int nearestValidPoint(int x, int y, int[][] points) {
        int manhattanDistance;
        int smallestManhattanDistance = Integer.MAX_VALUE;
        int smallestManhattanDistanceIndex = -1;
        for(int i = 0; i < points.length; i++) {
            if(x == points[i][0] || y == points[i][1]) {
                manhattanDistance = Math.abs(x - points[i][0]) + Math.abs(y - points[i][1]);
                if(manhattanDistance < smallestManhattanDistance) {
                    smallestManhattanDistance = manhattanDistance;
                    smallestManhattanDistanceIndex = i;
                }
            }
        }
        return smallestManhattanDistanceIndex;
    }
