class Solution {
public:

vector<int>Nearest_Smallest_left(vector<int>v){
    stack<int>st;
    int n = v.size();
    vector<int>left_min(n);
    left_min[0] = -1;
    st.push(0);
    for(int i=1; i<n; i++){
        while(st.size() && v[st.top()] >= v[i]) st.pop();
        if(st.empty()) left_min[i] = -1;
        else left_min[i] = st.top();
        st.push(i);
    }
    return left_min;
}



vector<int>Nearest_Smallest_right(vector<int>v){
    stack<int>st;
    int n = v.size();
    vector<int>right_min(n);
    right_min[n-1] = n;
    st.push(n-1);
    for(int i=n-2; i>=0; i--){
        while(st.size() && v[st.top()] >= v[i]) st.pop();
        if(st.empty()) right_min[i] = n;
        else right_min[i] = st.top();
        st.push(i);
    }
    return right_min;
}
int maximumScore(vector<int>& nums, int k) {
        int n = nums.size();
        int ans = 0;
        vector<int>left_smallest = Nearest_Smallest_left(nums);
        vector<int>right_smallest = Nearest_Smallest_right(nums);

        for(int i = 0; i < n; i++){
            int left = left_smallest[i] , right = right_smallest[i];
            if(k > left && k <right){
                ans = max(ans, nums[i] * (right - left - 1));  // upto what num[i] is minimum 
            }
        }
        return ans;
    }
};,66,https://leetcode.com/problems/maximum-score-of-a-good-subarray,https://leetcode.com/problems/maximum-score-of-a-good-subarray/solutions/4194794/simple-c-solution-using-stack-nearest-smallest-left-right-intuition/

class AuthenticationManager {
    int ttl;
    unordered_map<string, int> tokens;
public:
    AuthenticationManager(int timeToLive) {
        ttl = timeToLive;
    }

    void generate(string tokenId, int currentTime) {
        tokens[tokenId] = currentTime + ttl;
    }

    void renew(string tokenId, int currentTime) {
        auto tokenIt = tokens.find(tokenId);
        if (tokenIt != end(tokens) && tokenIt->second > currentTime) {
            tokenIt->second = currentTime + ttl;
        }
    }

    int countUnexpiredTokens(int currentTime) {
        int res = 0;
        for (auto token: tokens) {
            if (token.second > currentTime) res++;
        }
        return res;
    }
};,157,https://leetcode.com/problems/design-authentication-manager,https://leetcode.com/problems/design-authentication-manager/solutions/1118956/c-clean-code-single-map-solution-explained/

